7	/**
8	 * Soft-match detection for {@code POST /api/owners}: an owner that is <em>not</em> a hard
9	 * ({@link OwnerIdentityKey identityKey}) duplicate but nonetheless shares an existing owner's
10	 * {@code lastName} and {@code postcode} while having a different telephone is still created, and
11	 * flagged. Sets {@code possibleDuplicate} to {@code true} and {@code possibleDuplicateOf} to the
12	 * matching owner's id when such a match exists; otherwise {@code possibleDuplicate} is {@code false}
13	 * and {@code possibleDuplicateOf} is left absent.
14	 *
15	 * <p>Runs after {@link CheckOwnerIdentityUnique} (so a hard duplicate has already been rejected with
16	 * 409 and never reaches here) and before {@link SaveOwner} (so the not-yet-saved owner is not
17	 * compared against itself). When more than one existing owner matches, the earliest (lowest id) is
18	 * reported, for a deterministic result.
19	 *
20	 * <p>An existing owner in the <em>same household</em> (same computed {@code householdId}) is never a
21	 * soft match: reaching here past the household-duplicate block means this owner is a declared
22	 * household member, and a declared member is not a suspected duplicate.
23	 */
24	public class AssignPossibleDuplicate {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String lastName = owner.getLastName();
28	        String postcode = owner.getPostcode();
29	        Integer matchId = null;
30	        if (lastName != null && postcode != null && !postcode.isBlank()) {
31	            String telephone = normalizeTelephone(owner.getTelephone());
32	            for (Owner existing : ownerRepository.findAll()) {
33	                if (owner.getId() != null && owner.getId().equals(existing.getId())) {
34	                    continue;
35	                }
36	                if (existing.getId() == null) {
37	                    continue;
38	                }
39	                if (!lastName.equalsIgnoreCase(existing.getLastName())) {
40	                    continue;
41	                }
42	                if (!postcode.equals(existing.getPostcode())) {
43	                    continue;
44	                }
45	                // A member of the same computed household is a declared member, not a suspected
46	                // duplicate.
47	                if (owner.getHouseholdId() != null
48	                        && owner.getHouseholdId().equals(existing.getHouseholdId())) {
49	                    continue;
50	                }
51	                // A shared telephone is a hard-duplicate concern, not a soft match.
52	                if (telephone.equals(normalizeTelephone(existing.getTelephone()))) {
53	                    continue;
54	                }
55	                if (matchId == null || existing.getId() < matchId) {
56	                    matchId = existing.getId();
57	                }
58	            }
59	        }
60	        owner.setPossibleDuplicate(matchId != null);
61	        owner.setPossibleDuplicateOf(matchId);
62	    }
63	
64	    private static String normalizeTelephone(String raw) {
65	        if (raw == null) {
66	            return "";
67	        }
68	        String normalized = E164Telephone.normalize(raw);
69	        return normalized != null ? normalized : raw.trim();
70	    }
71	}
